// 电阻检查程序
// 检查50个电阻值是否在允许的误差范围内

datatype Resistor = Resistor(value: real, tolerance: real)

// 检查单个电阻是否在允许范围内
function CheckResistor(nominal: real, resistor: Resistor, minTol: real, maxTol: real): bool
  requires nominal > 0.0
  requires minTol <= maxTol
{
  // 计算实际值与标称值的百分比误差
  var actualError := (resistor.value - nominal) / nominal * 100.0;
  // 检查是否在允许范围内
  minTol <= actualError && actualError <= maxTol
}

// 检查一组电阻
method CheckResistors(resistors: seq<Resistor>, nominal: real, minTol: real, maxTol: real) 
  returns (results: seq<bool>)
  requires nominal > 0.0
  requires minTol <= maxTol
  requires |resistors| > 0
  ensures |results| == |resistors|
{
  results := [];
  var i := 0;

  while i < |resistors|
    invariant 0 <= i <= |resistors|
    invariant |results| == i
  {
    var isValid := CheckResistor(nominal, resistors[i], minTol, maxTol);
    results := results + [isValid];
    i := i + 1;
  }
}

